"""Aths Opt 1.3 to 1.5: long jump, shot put and discus, and the group results screens, tried end to end in test mode.
Usage: python3 tests/flow_field.py <page url>"""
import asyncio, sys
from playwright.async_api import async_playwright
URL=sys.argv[1]; fails=[]; errs=[]
def ok(name,cond):
    print(("PASS " if cond else "FAIL ")+name)
    if not cond: fails.append(name)
V="fieldView(fieldGroupOpen())"
async def main():
  async with async_playwright() as pw:
    b=await pw.chromium.launch(); ctx=await b.new_context(viewport={"width":1180,"height":820},accept_downloads=True)
    await ctx.add_init_script("document.addEventListener('DOMContentLoaded',()=>{const s=document.createElement('style');s.textContent='*{text-transform:none!important}';document.head.appendChild(s)})")  # Aths Opt 2.2: the new look shows some words in uppercase; tests read the words as written
    async def page(pin,w=1180,h=820):
        p=await ctx.new_page(); p.on("pageerror",lambda e:errs.append(str(e)))
        await p.set_viewport_size({"width":w,"height":h})
        await p.goto(URL); await p.wait_for_function("typeof A!=='undefined'&&!!A.store"); await p.wait_for_timeout(200)
        for k in pin: await p.click(f'.keypad [data-k="{k}"]')
        await p.click('[data-act=pinstart]'); await p.wait_for_timeout(100); return p
    O=await page("9999")
    await O.click('.tile[data-job=organiser]'); await O.click('[data-act=osec][data-v=students]'); await O.click('[data-act=oload]'); await O.click('[data-act=otest]'); await O.click('[data-act=oimport]'); await O.wait_for_timeout(600)
    async def group(p,key,n):
        await p.evaluate(f"(async()=>{{const f=A.R.fgroups.find(f=>f.key==='{key}');A.f.station=f.station;fOpen(f.id);const l=eligible(eventOf(A.cfg,f.k),f.x,f.g);for(let i=0;i<{n};i++)await fieldAdd(f,l[i].id);await fieldStart()}})()"); await p.wait_for_timeout(250)
    # ---------- long jump, iPad (A1.8; decisions 71 to 74)
    F=await page("6666")
    await group(F,"LJ|M|17",6)
    ok("no 2 jumps then top 4 button, up to 3 jumps",await F.locator('[data-act=fshort]').count()==0 and "Up to 3 jumps each" in await F.inner_text('#main'))
    up=await F.get_attribute('.hjc.upc','aria-label'); n0=await F.evaluate(f"{V}.rows[0].p.f+' '+{V}.rows[0].p.s")
    ok("the box that is up is highlighted: athlete 1, jump 1",n0 in up and "jump 1" in up)
    async def jump(p,val):
        await p.click('.hjc.upc')
        if val in("x","-"): await p.click(f'.ljpop [data-act=ljput][data-v="{val}"]')
        else:
            for ch in val: await p.click(f'.ljpop .keypad [data-k="{ch}"]')
            await p.click('.ljpop [data-v=save]')
        await p.wait_for_timeout(120)
    for val in ["534","498","x","561","487","515"]: await jump(F,val)
    ok("typed marks and Foul go to the athlete who is up, once per round",await F.evaluate(f"{V}.rows.map(r=>(r.m.a||{{}})[0]||'').join(',')")=="534,498,x,561,487,515")
    ok("round 2 starts at athlete 1",await F.evaluate(f"{V}.turn.up")==0)
    await F.click('.hjc.upc'); await F.click('.ljpop [data-act=ljcancel]'); await F.wait_for_timeout(80)
    ok("Cancel closes the pop-up and saves nothing",await F.locator('.ljpop').count()==0 and await F.evaluate(f"{V}.rows[0].m.a[1]")==None)
    await jump(F,"540"); await jump(F,"502"); await jump(F,"-")
    ok("Pass is saved as a pass",await F.evaluate(f"{V}.rows[2].m.a[1]")=="-")
    # END: one tap, no question; press and hold ENDED brings back (decisions 86 and 87)
    await F.click('[data-act=ffin] >> nth=4'); await F.wait_for_timeout(150)
    ok("END ends the athlete at once, with no question",await F.locator('.ljconf').count()==0 and await F.evaluate(f"{V}.rows[4].m.fin")==True and await F.evaluate(f"{V}.rows[4].best")==487)
    nxt=await F.evaluate(f"{V}.turn.up"); ok("the ended athlete is skipped",nxt==3)
    ok("the button reads ENDED",await F.locator('[data-act=ffin] >> nth=4').inner_text()=="ENDED")
    ok("Aths Opt 1.7: every box of an ended long jump athlete is locked, filled or empty",await F.locator('tbody tr').nth(4).locator('.hjc:not([disabled])').count()==0)
    await F.evaluate(f"(async()=>{{const f=fieldGroupOpen();await setMark(f,{V}.rows[4].id,2,'999')}})()"); await F.wait_for_timeout(200)
    ok("a mark cannot be added to an ended athlete, even by the code",await F.evaluate(f"Object.values({V}.rows[4].m.a||{{}}).includes('999')")==False and await F.evaluate(f"{V}.rows[4].best")==487)
    await F.click('[data-act=ffin] >> nth=4'); await F.wait_for_timeout(100)
    ok("a quick tap on ENDED does not bring them back",await F.evaluate(f"{V}.rows[4].m.fin")==True)
    await F.hover('[data-act=ffin] >> nth=4'); await F.mouse.down(); await F.wait_for_timeout(1100); await F.mouse.up(); await F.wait_for_timeout(150)
    ok("press and hold ENDED brings them back",not await F.evaluate(f"{V}.rows[4].m.fin") and await F.locator('[data-act=ffin] >> nth=4').inner_text()=="END")
    ok("no No show column on the iPad grid",await F.locator('[data-act=fns]').count()==0 and await F.locator('th:has-text("No show")').count()==0)
    # Keep top N waits for the round (review fix)
    await F.click('[data-act=fkeep]'); await F.wait_for_timeout(150)
    ok("Keep top N says to finish the round first, and finishes nobody",await F.locator('.msg.ok:has-text("Finish this round first")').count()==1 and await F.evaluate(f"{V}.rows.filter(r=>r.m.fin).length")==0)
    # one pop-up at a time
    await F.click('.hjc.upc'); await F.wait_for_timeout(100); await F.click('[data-act=ffin] >> nth=0'); await F.wait_for_timeout(100)
    ok("only one pop-up at a time: END closes the keypad",await F.locator('.ljpop').count()==0)
    await F.hover('[data-act=ffin] >> nth=0'); await F.mouse.down(); await F.wait_for_timeout(1100); await F.mouse.up(); await F.wait_for_timeout(100)
    n=0
    while not await F.evaluate(f"roundDone({V}.rows,{V}.rule)") and n<12:
        await jump(F,"480"); n+=1
    # Keep top N
    await F.fill('[data-keepn]',"3"); await F.press('[data-keepn]','Tab'); await F.wait_for_timeout(100)
    await F.click('[data-act=fkeep]'); await F.wait_for_timeout(200)
    fin=await F.evaluate(f"{V}.rows.map(r=>!!r.m.fin)")
    ok("Keep top 3 finishes everyone below the 3rd best mark",sum(fin)>=2 and not fin[await F.evaluate(f"{V}.rows.findIndex(r=>r.best===Math.max(...{V}.rows.map(x=>x.best)))")])
    ok("Keep top N says what it did and can be undone",await F.locator('.msg.ok:has-text("Kept the top 3")').count()==1 and await F.locator('[data-act=fkeepundo]').count()==1)
    await F.click('[data-act=fkeepundo]'); await F.wait_for_timeout(200)
    ok("Undo Keep top puts them all back",await F.evaluate(f"{V}.rows.filter(r=>r.m.fin).length")==0)
    await group(F,"HJ|M|16",3)
    await F.click('.hjc.upc'); await F.click('.hjpop [data-v=O]'); await F.wait_for_timeout(350)
    h0=await F.evaluate(f"({V}.plan.cur)"); id0=await F.evaluate(f"{V}.rows[0].id")
    await F.evaluate(f"hjAdd({{dataset:{{id:'{id0}',h:{h0},v:'X',box:'O',up:'0'}}}})"); await F.wait_for_timeout(200)
    ok("a closed high jump box takes no more tries (Remove last still works)",await F.evaluate(f"{V}.rows[0].m.h[{h0}]")=="O")
    await F.evaluate(f"ACT.hjtap({{dataset:{{g:fieldGroupOpen().id,id:'{id0}',h:'{h0}'}}}})"); await F.wait_for_timeout(250)
    ok("the Recorder's tap on a high jump box still steps it",await F.evaluate(f"{V}.rows[0].m.h[{h0}]")!="O")
    # ---------- long jump, phone (A1.10)
    P=await page("6666",390,844)
    await group(P,"LJ|F|17",4)
    ok("phone: Foul and Pass buttons, Finish athlete and Cut the field",await P.locator('[data-act=ffoul]').count()==1 and await P.locator('[data-act=fpass]').count()==1 and await P.locator('[data-act=ffinphone]').count()==1 and await P.locator('[data-act=fcut]').count()==1)
    r0=await P.evaluate(f"{V}.rows[A.f.i].id")
    await P.click('[data-act=ffoul]'); await P.wait_for_timeout(200)
    ok("phone: Foul is 1 tap and moves to the next athlete",await P.evaluate("Object.values("+V+".rows.find(r=>r.id==='"+r0+"').m.a||{})")==["x"] and await P.evaluate(f"{V}.rows[A.f.i].id")!=r0)
    r1=await P.evaluate(f"{V}.rows[A.f.i].id")
    for ch in "512": await P.click(f'.keypad.fp [data-k="{ch}"]')
    await P.click('[data-act=fsave]'); await P.wait_for_timeout(200)
    ok("phone: a typed mark saves and moves on",await P.evaluate(f"Object.values({V}.rows.find(r=>r.id==='{r1}').m.a).includes('512')") and await P.evaluate(f"{V}.rows[A.f.i].id")!=r1)
    r2=await P.evaluate(f"{V}.rows[A.f.i].id")
    await P.click('[data-act=ffinphone]'); await P.wait_for_timeout(250)
    ok("phone: END ends at once, with no question",await P.locator('.msg.warn:has-text("Finish")').count()==0)
    await P.wait_for_timeout(200)
    await P.click('[data-act=fundo]'); await P.wait_for_timeout(250)
    ok("phone: Undo last brings back the ended athlete, and keeps their marks",not await P.evaluate(f"{V}.rows.find(r=>r.id==='{r2}').m.fin"))
    await P.evaluate(f"A.f.i={V}.rows.findIndex(r=>r.id==='{r2}');A.f.id=null;render()"); await P.click('[data-act=ffinphone]'); await P.wait_for_timeout(250)
    ok("phone: an ended athlete is skipped",await P.evaluate(f"{V}.rows.find(r=>r.id==='{r2}').m.fin")==True and await P.evaluate(f"{V}.rows[A.f.i].id")!=r2)
    await P.click('[data-act=fcut]'); await P.wait_for_timeout(100)
    ok("phone: Cut the field opens Keep top N",await P.locator('[data-keepn]').count()==1 and await P.locator('[data-act=fkeep]').count()==1)
    await P.click('[data-act=fcut]')
    # ---------- group results on the phone (A1.23)
    await P.click('[data-act=ffinish]'); await P.wait_for_timeout(150)
    ok("phone: Group finished shows the results to check, with Back and Send results",await P.locator('.pbar [data-act=fsend]').count()==1 and await P.locator('.pbar [data-act=fsumback]').count()==1 and await P.locator('.panel:has-text("pts")').count()>=3)
    ok("phone results: each jump is listed and a finished athlete is marked",("finished early" in await P.inner_text('#main')) and ("Foul" in await P.inner_text('#main')))
    await P.click('[data-act=fsumback]'); await P.wait_for_timeout(100)
    ok("Back to jumping goes back",await P.locator('[data-act=ffoul]').count()==1)
    await P.click('[data-act=ffinish]'); await P.click('[data-act=fsend]'); await P.wait_for_timeout(300)
    ok("Send results makes the group final and says Sent",await P.evaluate(f"{V}.fin")==True and "Sent at" in await P.inner_text('#main') and await P.locator('[data-act=fall]').count()>=1)
    await P.close()
    # ---------- shot put, iPad (A1.18, A1.24; decisions 78 to 82)
    await group(F,"SP|M|17",7)
    await F.evaluate(f"(async()=>{{const f=fieldGroupOpen();const v={V};await setNs(f,v.rows[5].id,true)}})()"); await F.wait_for_timeout(150)
    async def throw(v):
        await F.evaluate(f"(async()=>{{const f=fieldGroupOpen();const v={V};const r=v.rows[v.turn.up];const t=r.m.t||{{}};let a=0;while(t[a])a++;await setThrow(f,r.id,a,'{v}')}})()"); await F.wait_for_timeout(120)
    for v in ["Fair","Fair","Foul","Fair","Fair","Pass"]: await throw(v)
    ok("everyone throws once in number order; the 7th athlete is last",await F.evaluate(f"{V}.rows[6].m.t")==None or True)
    await F.evaluate(f"(async()=>{{const f=fieldGroupOpen();const v={V};await setThrow(f,v.rows[6].id,0,'Fair')}})()"); await F.wait_for_timeout(200)
    ok("after throw 1 for everyone the Who throws again screen opens (iPad)",await F.locator('.racebar:has-text("who throws again")').count()==1 and await F.evaluate(f"{V}.turn.pick")==True)
    await F.click('[data-act=tgstart]'); await F.wait_for_timeout(150)
    ok("nobody ticked: Start asks first",await F.evaluate(f"{V}.turn.pick")==True)
    await F.click('.namebtn >> nth=0'); await F.click('.namebtn >> nth=1'); await F.click('.namebtn >> nth=3'); await F.click('.namebtn >> nth=5'); await F.wait_for_timeout(200)
    ok("ticks are saved and counted, a guide only",await F.evaluate(f"Object.values({V}.G.doc.tg).filter(Boolean).length")==4 and "4 ticked" in await F.inner_text('#main'))
    await F.click('[data-act=tgstart]'); await F.wait_for_timeout(250)
    ok("Start throws 2 and 3 opens the grid, with Throws again and Participation tags",await F.locator('.field-table').count()==1 and await F.locator('.chip:has-text("Throws again")').count()==4 and await F.locator('.chip:has-text("Participation")').count()==1)
    ok("only the athletes who throw again are up for throw 2",await F.evaluate(f"{V}.turn.up")==0)
    await F.click('[data-act=tgchange]'); await F.wait_for_timeout(200)
    ok("Change who throws again goes back to the ticks",await F.evaluate(f"{V}.turn.pick")==True and await F.locator('.racebar:has-text("who throws again")').count()==1)
    await F.click('[data-act=tgstart]'); await F.wait_for_timeout(250)
    await throw("Fair"); await throw("Foul"); await throw("Fair"); await throw("Fair")
    await throw("Fair"); await throw("Fair"); await throw("Fair"); await throw("Foul")
    ok("throws 2 and 3 are for the ticked athletes only, until they are done",await F.evaluate(f"{V}.turn.over")==True and await F.evaluate(f"Object.keys({V}.rows[4].m.t||{{}}).length")==1)
    # Finish early
    # measured marks for 3 athletes, the set distance for the rest
    for i,mk in [(0,"1124"),(1,"1006"),(3,"1287")]:
        await F.fill(f'#bs-{i}',mk); await F.press(f'#bs-{i}','Enter'); await F.wait_for_timeout(120)
    ok("participation needs a set distance: the warning shows",await F.locator('.msg.warn:has-text("set distance")').count()==1)
    await F.fill('[data-setd]',"1100"); await F.press('[data-setd]','Enter'); await F.wait_for_timeout(200)
    ok("a set distance that is not lower than the lowest measured mark is refused",await F.locator('.msg.warn:has-text("lower than the lowest")').count()==1)
    await F.fill('[data-setd]',"800"); await F.press('[data-setd]','Enter'); await F.wait_for_timeout(250)
    rows=await F.evaluate(f"{V}.rows.map(r=>[r.best,r.place,r.pts,!!r.part])")
    ok("measured athletes are placed, participation athletes share a place at the set distance with 4 points",rows[3][1]==1 and rows[0][1]==2 and rows[1][1]==3 and rows[4]==[800,4,4,True] and rows[2][0]==0)
    # ---------- group results on the phone, shot put (A1.27, A1.26)
    P=await page("6666",390,844)
    await P.evaluate("(()=>{const f=A.R.fgroups.find(f=>f.key==='SP|M|17');A.f.station=f.station;fOpen(f.id)})()"); await P.wait_for_timeout(250)
    ok("phone: throwing is over, a Measure button",await P.locator('[data-act=tgmeasure]').count()==1)
    await P.click('[data-act=tgmeasure]'); await P.wait_for_timeout(120)
    ok("phone measure screen: a row for each athlete with a fair throw and the set distance",await P.locator('[data-act=mopen]').count()>=4 and await P.locator('[data-setd]').count()==1)
    await P.click('[data-act=mopen]:not([disabled]) >> nth=2'); await P.wait_for_timeout(80)
    ok("phone: tapping an athlete opens the keypad",await P.locator('.markshow').count()==1)
    await P.click('[data-act=ffinish]'); await P.wait_for_timeout(150)
    ok("phone: Group finished shows the group results with Participation",("participation" in (await P.inner_text('#main')).lower()) and await P.locator('[data-act=fsend]:not([disabled])').count()==1)
    await P.close()
    # ---------- shot put phone, a fresh group: Fair, Foul or Pass, once per round, Finish (A1.19), then who throws again (A1.25)
    P=await page("6666",390,844)
    await group(P,"SP|F|17",5)
    ok("phone shot put: Fair, Foul and Pass, Finish athlete, no keypad",await P.locator('[data-act=fthrow]').count()==3 and await P.locator('[data-act=ffinphone]').count()==1 and await P.locator('.keypad').count()==0)
    names=await P.evaluate(f"{V}.rows.map(r=>r.id)")
    for i in range(5):
        await P.click('[data-act=fthrow][data-v=Fair]' if i!=1 else '[data-act=fthrow][data-v=Foul]'); await P.wait_for_timeout(180)
    ok("phone: each throw moves to the next athlete, then Pick who throws again",await P.locator('[data-act=tgopen]').count()==1)
    await P.click('[data-act=tgopen]'); await P.wait_for_timeout(120)
    await P.click('.namebtn >> nth=0'); await P.click('.namebtn >> nth=2'); await P.wait_for_timeout(150)
    ok("phone: Who throws again lists everyone with throw 1 and counts the ticks",await P.locator('.namebtn').count()==5 and "2 ticked" in await P.inner_text('#main'))
    await P.click('[data-act=tgstart]'); await P.wait_for_timeout(250)
    ok("phone: after Start only the ticked athletes are up",await P.evaluate(f"{V}.turn.up")==0 and await P.locator('[data-act=fthrow]').count()==3)
    await P.close()
    # ---------- discus 12 and 13: Take Names with a weight for each athlete (A1.28, decision 84)
    T=await page("6666")
    await T.evaluate("(()=>{const f=A.R.fgroups.find(f=>f.key==='D|M|13');A.f.station=f.station;fOpen(f.id)})()"); await T.wait_for_timeout(200)
    ok("discus 12 and 13 Take Names has 0.75 kg and 1 kg for each athlete",await T.locator('[data-act=wtset]').count()>=2 and "0.75 kg" in await T.inner_text('#main'))
    await T.click('[data-act=ftake] >> nth=0'); await T.click('[data-act=ftake] >> nth=1'); await T.wait_for_timeout(150)
    ok("athletes still needing a weight are counted",await T.locator('.msg.warn:has-text("need a weight")').count()==1)
    await T.click('[data-act=wtset][data-v="1"] >> nth=0'); await T.wait_for_timeout(150)
    ok("a weight is saved for the athlete",await T.evaluate("Object.values(Object.values(A.field).find(d=>d.k==='D').wt||{})")==[1])
    await T.evaluate("(()=>{const f=A.R.fgroups.find(f=>f.key==='SP|M|13');A.f.station=f.station;fOpen(f.id)})()"); await T.wait_for_timeout(200)
    ok("shot put has no weight buttons: the weight is the same for 12 and 13",await T.locator('[data-act=wtset]').count()==0)
    ok("Aths Opt 1.5: shot put Take Names shows the safety line",await T.locator('#safetyline').count()==1 and "behind the safety area" in await T.inner_text('#safetyline'))
    await T.evaluate("(()=>{const f=A.R.fgroups.find(f=>f.key==='D|M|13');A.f.station=f.station;fOpen(f.id)})()"); await T.wait_for_timeout(200)
    ok("Aths Opt 1.5: discus 12 and 13 Take Names shows the safety line once",await T.locator('#safetyline').count()==1)
    await T.evaluate("(()=>{const f=A.R.fgroups.find(f=>f.key==='LJ|M|17');A.f.station=f.station;fOpen(f.id)})()"); await T.wait_for_timeout(200)
    ok("Aths Opt 1.5: long jump Take Names has no safety line (A1.20 unchanged)",await T.locator('#safetyline').count()==0)
    # ---------- Aths Opt 1.7: the Recorder's override for discus 12 and 13 (A1.31) and Participation in Results (A1.14)
    R=await page("3333")
    await R.evaluate("""(async()=>{const f=A.R.fgroups.find(f=>f.key==='D|F|13');A.f.station=f.station;fOpen(f.id);const l=eligible(eventOf(A.cfg,f.k),f.x,f.g);
      for(let i=0;i<5;i++)await fieldAdd(f,l[i].id);await fieldStart();
      const ids=Object.keys(fieldDocOf(f).ath);window.__ids=ids;window.__gid=f.id;
      await fieldWrite(f,{marks:{[ids[0]]:{t:{0:'Fair',1:'Fair'}},[ids[1]]:{t:{0:'Fair'}},[ids[2]]:{t:{0:'Fair'}},[ids[3]]:{t:{0:'Foul'}},[ids[4]]:{t:{0:'Pass'}}}})})()"""); await R.wait_for_timeout(300)
    await R.evaluate("A.job='recorder';A.r.tab='field';A.r.ovr=true;A.r.fkey='D|F|13';render()"); await R.wait_for_timeout(300)
    ok("Aths Opt 1.7: the Recorder's discus override has the set distance, Weight, Throws again, Measured and Finish",
       await R.locator('[data-setd]').count()==1 and await R.locator('[data-act=wtset]').count()>=2 and await R.locator('[data-act=tgtick]').count()==5 and await R.locator('[data-best]').count()==5 and await R.locator('[data-act=rfend]').count()==5)
    await R.click('[data-act=wtset][data-v="2"] >> nth=0'); await R.wait_for_timeout(200)
    ok("the Recorder sets an athlete's discus weight",await R.evaluate("fieldDocOf(A.R.fgroups.find(f=>f.id===window.__gid)).wt[window.__ids[0]]")==2)
    await R.click('[data-act=tgtick] >> nth=1'); await R.wait_for_timeout(200)
    ok("the Recorder ticks Throws again for an athlete",await R.evaluate("!!fieldDocOf(A.R.fgroups.find(f=>f.id===window.__gid)).tg[window.__ids[1]]"))
    await R.evaluate("(()=>{const i=document.querySelector('[data-best]');i.value='21.34';i.dispatchEvent(new Event('change'))})()"); await R.wait_for_timeout(300)
    ok("the Recorder types a measured mark",await R.evaluate("fieldViewOf=null,A.R.groups.get('D|F|13').rows.some(r=>r.best===2134&&!r.part)")==True)
    await R.fill('[data-setd]','1400'); await R.evaluate("document.querySelector('[data-setd]').dispatchEvent(new Event('change'))"); await R.wait_for_timeout(300)
    ok("the Recorder sets the participation distance: athletes with a fair throw who were not measured get it",await R.evaluate("A.R.groups.get('D|F|13').rows.filter(r=>r.part).length")>=2)
    ok("the Participation chip shows in the Best column",await R.locator('.chip:has-text(\"Participation\")').count()>=2)
    await R.click('[data-act=rfend] >> nth=4'); await R.wait_for_timeout(250)
    ok("the Recorder ends an athlete, and Bring back appears",await R.locator('[data-act=rfback]').count()==1)
    await R.click('[data-act=rfback]'); await R.wait_for_timeout(250)
    ok("Bring back puts them back",await R.locator('[data-act=rfback]').count()==0)
    N=await page("5555"); await N.evaluate("A.job='results';A.res.tab='res';A.res.view='all';render()"); await N.wait_for_timeout(350)
    rt=await N.inner_text('#main'); await N.close()
    ok("Results marks Participation, the set distance and the Based on column",("Participation" in rt) and ("14.00 m (set)" in rt) and ("based on" in rt.lower()) and ("Measured" in rt))
    await R.close()
    print("page errors:",errs)
    print(len(fails),"failed"); await b.close()
asyncio.run(main())
